<?php
namespace App\Http\Controllers\Api\V1;
use App\Http\Requests\ExecuteTransferRequest; use App\Http\Requests\TransferQuoteRequest; use App\Http\Resources\TransferQuoteResource; use App\Http\Resources\TransferResource; use App\Models\Beneficiary; use App\Models\BeneficiaryAccount; use App\Models\Transfer; use App\Models\TransferQuote; use App\Models\WalletCurrencyAccount; use App\Services\TransferQuoteService; use App\Services\TransferService; use App\Services\TransferStepUpService; use Illuminate\Http\JsonResponse; use Illuminate\Http\Request;
final class TransferController
{
    public function stepUp(Request $request, TransferStepUpService $service): JsonResponse { return response()->json(['data'=>$service->issue($request->user()),'sandbox_only'=>true],201); }
    public function quote(TransferQuoteRequest $request, TransferQuoteService $service): JsonResponse { $source=WalletCurrencyAccount::findOrFail($request->string('source_wallet_currency_account_id')->toString()); $beneficiary=Beneficiary::findOrFail($request->string('beneficiary_id')->toString()); $account=BeneficiaryAccount::where('beneficiary_id',$beneficiary->id)->findOrFail($request->string('beneficiary_account_id')->toString()); return response()->json(['data'=>new TransferQuoteResource($service->create($request->user(),$source,$beneficiary,$account,(int)$request->integer('source_amount_minor'))),'sandbox_only'=>true],201); }
    public function quoteShow(Request $request, TransferQuote $quote): JsonResponse { abort_unless((string)$quote->user_id===(string)$request->user()->id,404); return response()->json(['data'=>new TransferQuoteResource($quote),'sandbox_only'=>true]); }
    public function execute(ExecuteTransferRequest $request, TransferService $service): JsonResponse { $quote=TransferQuote::findOrFail($request->string('quote_id')->toString()); $transfer=$service->execute($request->user(),$quote,(string)$request->header('Idempotency-Key'),$request->string('challenge_id')->toString(),$request->string('challenge_code')->toString(),$request->string('provider_scenario','accepted')->toString()); return response()->json(['data'=>new TransferResource($transfer),'sandbox_only'=>true]); }
    public function index(Request $request): JsonResponse { $rows=Transfer::with('beneficiary')->where('user_id',$request->user()->id)->latest()->paginate(10); return response()->json(['data'=>TransferResource::collection($rows->items()),'meta'=>['current_page'=>$rows->currentPage(),'last_page'=>$rows->lastPage(),'per_page'=>10,'total'=>$rows->total()],'sandbox_only'=>true]); }
    public function show(Request $request, Transfer $transfer): JsonResponse { abort_unless((string)$transfer->user_id===(string)$request->user()->id,404); return response()->json(['data'=>new TransferResource($transfer->load(['beneficiary','events','screenings','attempts','receipt'])),'sandbox_only'=>true]); }
    public function timeline(Request $request, Transfer $transfer): JsonResponse { abort_unless((string)$transfer->user_id===(string)$request->user()->id,404); return response()->json(['data'=>$transfer->events()->latest('created_at')->get(),'sandbox_only'=>true]); }
    public function receipt(Request $request, Transfer $transfer): JsonResponse { abort_unless((string)$transfer->user_id===(string)$request->user()->id,404); return response()->json(['data'=>$transfer->receipt,'sandbox_only'=>true]); }
    public function cancel(Request $request, Transfer $transfer, TransferService $service): JsonResponse { return response()->json(['data'=>new TransferResource($service->cancel($request->user(),$transfer)),'sandbox_only'=>true]); }
}
